//! SPEC §§3–4: direct evaluators of natural-coefficient messages.

use super::{
    basis,
    domain::{self, FibreIndex, InitialIndex, Point},
    CodeField, FinalMessage, Message,
};

/// SPEC §3: evaluations of (p0_q,p1_q) at x in O(512) field operations.
pub fn eval_pair<E: CodeField>(q: &Message<E>, x: E) -> (E, E) {
    let basis = basis::values::<E, 512>(x);
    let mut p0 = E::ZERO;
    let mut p1 = E::ZERO;
    for (pair, n) in q.chunks_exact(2).zip(basis) {
        p0 = p0.add(pair[0].mul(n));
        p1 = p1.add(pair[1].mul(n));
    }
    (p0, p1)
}
pub fn p0_q<E: CodeField>(q: &Message<E>, x: E) -> E {
    eval_pair(q, x).0
}
pub fn p1_q<E: CodeField>(q: &Message<E>, x: E) -> E {
    eval_pair(q, x).1
}

/// SPEC §3: evalMessage(q,(x,y))=p0_q(x)+y*p1_q(x), including OOD.
pub fn eval_message<E: CodeField>(q: &Message<E>, z: Point<E>) -> E {
    let (p0, p1) = eval_pair(q, z.x);
    p0.add(z.y.mul(p1))
}
/// SPEC §3: Enc(q)[i]; a word is represented by its pointwise evaluator.
pub fn exact_initial_encoder<E: CodeField>(q: &Message<E>, i: InitialIndex) -> E {
    eval_message(q, domain::stored_point(i))
}
/// SPEC §4: Σ_d F[d]*N_d(line_node(u)), with 256 natural coefficients.
pub fn exact_final_encoder<E: CodeField>(q: &FinalMessage<E>, u: FibreIndex) -> E {
    q.iter()
        .zip(basis::values::<E, 256>(domain::line_node(u)))
        .fold(E::ZERO, |sum, (&coefficient, n)| {
            sum.add(coefficient.mul(n))
        })
}

//! SPEC §3: Chebyshev-product natural basis and coefficient conversions.

use super::{CodeField, Error};
use crate::field::M31;
use alloc::vec::Vec;

/// SPEC §3: evaluate D_b, with D_0=X, D_(b+1)=2 D_b²−1.
pub fn doubled_factor<E: CodeField>(b: usize, x: E) -> E {
    let mut d = x;
    for _ in 0..b {
        d = double(d);
    }
    d
}

pub(crate) fn double<E: CodeField>(x: E) -> E {
    let square = x.mul(x);
    square.add(square).sub(E::ONE)
}

/// SPEC §3: evaluate N_j=∏_{b in bits(j)} D_b (including N_0=1).
pub fn natural<E: CodeField>(mut j: usize, x: E) -> E {
    let mut factor = x;
    let mut out = E::ONE;
    while j != 0 {
        if j & 1 != 0 {
            out = out.mul(factor);
        }
        j >>= 1;
        if j != 0 {
            factor = double(factor);
        }
    }
    out
}

pub(crate) fn values<E: CodeField, const N: usize>(x: E) -> [E; N] {
    let mut out = [E::ONE; N];
    let mut width = 1;
    let mut factor = x;
    while width < N {
        for j in 0..width.min(N - width) {
            out[width + j] = out[j].mul(factor);
        }
        width *= 2;
        factor = double(factor);
    }
    out
}

/// The only two conversion sizes in SPEC §3.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BasisSize {
    Initial,
    Final,
}

impl BasisSize {
    pub const fn len(self) -> usize {
        match self {
            Self::Initial => 512,
            Self::Final => 256,
        }
    }
    pub const fn is_empty(self) -> bool {
        false
    }
}

/// SPEC §3: M_n[d,j]=[X^d]N_j and M_n⁻¹, in row-major order.
///
/// Entries lie in F; application embeds them into any CodeField. Generation
/// uses D's polynomial recurrence, then triangular back-substitution. No
/// elimination in E or huge stack-resident matrix is needed. Retain/reuse this
/// object across chord operations (M_512 and its inverse take 2 MiB total).
pub struct NaturalBasis {
    size: BasisSize,
    matrix: Vec<M31>,
    inverse: Vec<M31>,
}

fn zero_vec(len: usize) -> Result<Vec<M31>, Error> {
    let mut result = Vec::new();
    result
        .try_reserve_exact(len)
        .map_err(|_| Error::Allocation)?;
    result.resize(len, M31::ZERO);
    Ok(result)
}

impl NaturalBasis {
    /// SPEC §3: generate M_512/M_256 and their inverses from the recurrence.
    pub fn new(size: BasisSize) -> Result<Self, Error> {
        let n = size.len();
        let mut matrix = zero_vec(n * n)?;
        let mut inverse = zero_vec(n * n)?;
        let mut d = zero_vec(n)?;
        let mut next = zero_vec(n)?;
        matrix[0] = M31::ONE;
        d[1] = M31::ONE;
        let mut width = 1;
        while width < n {
            // N_(width+j)=D_log2(width)*N_j, for j<width.
            for j in 0..width {
                for k in 0..=width {
                    if d[k] == M31::ZERO {
                        continue;
                    }
                    for t in 0..=j {
                        let old = matrix[t * n + j];
                        if old != M31::ZERO {
                            let index = (k + t) * n + width + j;
                            matrix[index] = matrix[index].add(d[k].mul(old));
                        }
                    }
                }
            }
            width *= 2;
            if width < n {
                next.fill(M31::ZERO);
                for k in 0..=width / 2 {
                    if d[k] == M31::ZERO {
                        continue;
                    }
                    for t in 0..=width / 2 {
                        next[k + t] = next[k + t].add(d[k].mul(d[t]).double());
                    }
                }
                next[0] = next[0].sub(M31::ONE);
                core::mem::swap(&mut d, &mut next);
            }
        }
        for j in 0..n {
            let diagonal =
                <M31 as CodeField>::try_inv(matrix[j * n + j]).ok_or(Error::ZeroDenominator)?;
            inverse[j * n + j] = diagonal;
            for i in (0..j).rev() {
                let mut sum = M31::ZERO;
                for k in i + 1..=j {
                    let a = matrix[i * n + k];
                    let b = inverse[k * n + j];
                    if a != M31::ZERO && b != M31::ZERO {
                        sum = sum.add(a.mul(b));
                    }
                }
                // Previously computed diagonal inverse of row i.
                inverse[i * n + j] = sum.neg().mul(inverse[i * n + i]);
            }
        }
        Ok(Self {
            size,
            matrix,
            inverse,
        })
    }

    pub const fn size(&self) -> BasisSize {
        self.size
    }
    pub fn matrix(&self) -> &[M31] {
        &self.matrix
    }
    pub fn inverse_matrix(&self) -> &[M31] {
        &self.inverse
    }

    /// SPEC §3: M * natural coefficients; both slices must have size n.
    pub fn natural_to_monomial<E: CodeField>(
        &self,
        input: &[E],
        output: &mut [E],
    ) -> Result<(), Error> {
        self.apply(&self.matrix, false, input, output)
    }
    /// SPEC §3: M⁻¹ * monomial coefficients; both slices must have size n.
    pub fn monomial_to_natural<E: CodeField>(
        &self,
        input: &[E],
        output: &mut [E],
    ) -> Result<(), Error> {
        self.apply(&self.inverse, false, input, output)
    }
    pub(crate) fn transpose<E: CodeField>(
        &self,
        inverse: bool,
        input: &[E],
        output: &mut [E],
    ) -> Result<(), Error> {
        self.apply(
            if inverse { &self.inverse } else { &self.matrix },
            true,
            input,
            output,
        )
    }
    fn apply<E: CodeField>(
        &self,
        matrix: &[M31],
        transpose: bool,
        input: &[E],
        output: &mut [E],
    ) -> Result<(), Error> {
        let n = self.size.len();
        if input.len() != n || output.len() != n {
            return Err(Error::WrongLength);
        }
        output.fill(E::ZERO);
        for row in 0..n {
            for col in row..n {
                let scalar = matrix[row * n + col];
                if scalar == M31::ZERO {
                    continue;
                }
                let (dst, src) = if transpose { (col, row) } else { (row, col) };
                output[dst] = output[dst].add(E::from_m31(scalar).mul(input[src]));
            }
        }
        Ok(())
    }
}

//! The generic field boundary shared by SPEC §§3–5.

use crate::field::{WideExact, CM31, M31, P, QM31};

/// A field with a unital M31 embedding (the Lean `[Algebra (ZMod P) E]`).
///
/// Implementors must obey field laws, return `None` exactly at zero from
/// `try_inv`, and make arithmetic non-panicking. The existing F/K/E tower
/// implements this interface. Its legacy public raw F/K representatives must
/// be canonical, as required by SPEC §1; WideExact enforces that invariant.
pub trait CodeField: Copy + Eq {
    const ZERO: Self;
    const ONE: Self;
    fn from_m31(value: M31) -> Self;
    fn add(self, rhs: Self) -> Self;
    fn sub(self, rhs: Self) -> Self;
    fn neg(self) -> Self;
    fn mul(self, rhs: Self) -> Self;
    fn try_inv(self) -> Option<Self>;
}

macro_rules! arithmetic {
    ($t:ty) => {
        const ZERO: Self = <$t>::ZERO;
        const ONE: Self = <$t>::ONE;
        fn add(self, rhs: Self) -> Self {
            <$t>::add(self, rhs)
        }
        fn sub(self, rhs: Self) -> Self {
            <$t>::sub(self, rhs)
        }
        fn neg(self) -> Self {
            <$t>::neg(self)
        }
        fn mul(self, rhs: Self) -> Self {
            <$t>::mul(self, rhs)
        }
    };
}

impl CodeField for M31 {
    arithmetic!(M31);
    fn from_m31(value: M31) -> Self {
        M31(value.0 % P)
    }
    fn try_inv(self) -> Option<Self> {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::FInvGeneric);
        if self == Self::ZERO {
            None
        } else {
            Some(self.pow(u64::from(P - 2)))
        }
    }
}
impl CodeField for CM31 {
    arithmetic!(CM31);
    fn from_m31(value: M31) -> Self {
        CM31::from_m31(<M31 as CodeField>::from_m31(value))
    }
    fn try_inv(self) -> Option<Self> {
        let norm = self.a.mul(self.a).add(self.b.mul(self.b));
        let inverse = <M31 as CodeField>::try_inv(norm)?;
        Some(Self {
            a: self.a.mul(inverse),
            b: self.b.neg().mul(inverse),
        })
    }
}
impl CodeField for QM31 {
    arithmetic!(QM31);
    fn from_m31(value: M31) -> Self {
        QM31::from_cm31(<CM31 as CodeField>::from_m31(value))
    }
    fn try_inv(self) -> Option<Self> {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::KInvGeneric);
        let r = CM31::new(M31(2), M31::ONE);
        let norm = self.c0.mul(self.c0).sub(r.mul(self.c1.mul(self.c1)));
        let inverse = <CM31 as CodeField>::try_inv(norm)?;
        Some(Self {
            c0: self.c0.mul(inverse),
            c1: self.c1.neg().mul(inverse),
        })
    }
}
impl CodeField for WideExact {
    arithmetic!(WideExact);
    fn from_m31(value: M31) -> Self {
        Self::from_qm31(<QM31 as CodeField>::from_m31(value))
    }
    fn try_inv(self) -> Option<Self> {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::EInvGeneric);
        let norm = self
            .c0()
            .mul(self.c0())
            .sub(Self::U.mul(self.c1().mul(self.c1())));
        let inverse = <QM31 as CodeField>::try_inv(norm)?;
        Some(Self::new(
            self.c0().mul(inverse),
            self.c1().neg().mul(inverse),
        ))
    }
}

//! The R0 wide field, independently of transcript sampling or proof encoding.

use super::{CM31, M31, P, QM31};

/// `E = QM31[v]/(v² - u)`, where `u² = 2+i` and `i² = -1`.
///
/// Exactly two QM31 coordinates, `c0 + c1*v`, or eight canonical M31 limbs.
/// For digits `d[0..8]` in `[0, P)`, the exact decode formula is
///
/// ```text
/// decode4(a,b,c,d) = (a + b*i) + (c + d*i)*u
/// decode8(d) = decode4(d0,d1,d2,d3) + decode4(d4,d5,d6,d7)*v
/// ```
///
/// Thus limb order is `(c0.c0.a, c0.c0.b, c0.c1.a, c0.c1.b,
/// c1.c0.a, c1.c0.b, c1.c1.a, c1.c1.b)`, matching
/// `R0C/ModuloField.lean:digitsField_apply` (lines 38–40) and
/// `AspisV8R19/SamplerFieldDecode.lean:decode4` (line 10).
/// `WideTower.lean:qm31_wideU_not_isSquare` supplies the mathematical
/// non-residue fact; `wideExact_card` gives `|E| = P^8`.
/// These references specify the arithmetic; they do not prove this Rust code.
///
/// Coordinates are private to preserve canonicality. Algebraic constructors
/// reduce raw QM31 representatives; wire/digit decoders reject noncanonical
/// input. All operations are total except inversion, which returns `None` at
/// zero. This reference implementation makes no constant-time claim.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct WideExact {
    c0: QM31,
    c1: QM31,
}

impl WideExact {
    pub const LIMB_COUNT: usize = 8;
    pub const BYTE_LEN: usize = 32;
    /// The QM31 generator, not `2+i`: `U = (0,1)` in QM31 coordinates.
    pub const U: QM31 = QM31 {
        c0: CM31::ZERO,
        c1: CM31::ONE,
    };
    pub const ZERO: Self = Self {
        c0: QM31::ZERO,
        c1: QM31::ZERO,
    };
    pub const ONE: Self = Self {
        c0: QM31::ONE,
        c1: QM31::ZERO,
    };
    pub const V: Self = Self {
        c0: QM31::ZERO,
        c1: QM31::ONE,
    };

    /// Construct `c0 + c1*v`, reducing each raw M31 representative modulo P.
    pub fn new(c0: QM31, c1: QM31) -> Self {
        Self {
            c0: canonical_qm31(c0),
            c1: canonical_qm31(c1),
        }
    }

    #[inline(always)]
    pub const fn c0(self) -> QM31 {
        self.c0
    }
    #[inline(always)]
    pub const fn c1(self) -> QM31 {
        self.c1
    }

    /// The field embedding `x -> x + 0*v`; canonicalizes raw QM31 limbs.
    #[inline(always)]
    pub fn from_qm31(value: QM31) -> Self {
        Self {
            c0: canonical_qm31(value),
            c1: QM31::ZERO,
        }
    }

    #[inline(always)]
    pub fn add(self, rhs: Self) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::EAdd);
        Self {
            c0: self.c0.add(rhs.c0),
            c1: self.c1.add(rhs.c1),
        }
    }

    #[inline(always)]
    pub fn sub(self, rhs: Self) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::ESub);
        Self {
            c0: self.c0.sub(rhs.c0),
            c1: self.c1.sub(rhs.c1),
        }
    }

    #[inline(always)]
    pub fn neg(self) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::ENeg);
        Self {
            c0: self.c0.neg(),
            c1: self.c1.neg(),
        }
    }

    /// `(a+b*v)(c+d*v) = (ac+u*bd) + (ad+bc)*v`.
    #[inline(always)]
    pub fn mul(self, rhs: Self) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::EMul);
        #[cfg(all(feature = "r0-e4-reference", not(target_os = "solana")))]
        if crate::r0::equality_trace::is_reference() {
            return self.mul_re3(rhs);
        }
        let ac = self.c0.mul(rhs.c0);
        let bd = self.c1.mul(rhs.c1);
        let cross = self.c0.add(self.c1).mul(rhs.c0.add(rhs.c1));
        Self {
            c0: ac.add(mul_u(bd)),
            c1: cross.sub(ac).sub(bd),
        }
    }

    /// Frozen schoolbook outer layer for the native R-E3 equality gate.
    #[cfg(all(feature = "r0-e4-reference", not(target_os = "solana")))]
    pub fn mul_re3(self, rhs: Self) -> Self {
        Self {
            c0: self.c0.mul(rhs.c0).add(mul_u(self.c1.mul(rhs.c1))),
            c1: self.c0.mul(rhs.c1).add(self.c1.mul(rhs.c0)),
        }
    }

    /// `(a+b*v)^2 = (a^2+u*b^2) + (2ab)*v`.
    #[inline(always)]
    pub fn square(self) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::ESquare);
        let cross = self.c0.mul(self.c1);
        Self {
            c0: self.c0.square().add(mul_u(self.c1.square())),
            c1: cross.add(cross),
        }
    }

    /// `(a+b*v)^-1 = (a-b*v)/(a^2-u*b^2)`. Returns `None` at zero.
    /// Since u is a nonsquare in QM31, the norm is nonzero for nonzero self.
    pub fn try_inv(self) -> Option<Self> {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::EInv);
        let norm = self.c0.square().sub(mul_u(self.c1.square()));
        let inverse_norm = norm.try_inv()?;
        Some(Self {
            c0: self.c0.mul(inverse_norm),
            c1: self.c1.neg().mul(inverse_norm),
        })
    }

    /// Binary exponentiation, with `0^0 = 1`, as for the existing tower.
    pub fn pow(self, mut exponent: u64) -> Self {
        let mut result = Self::ONE;
        let mut base = self;
        while exponent != 0 {
            if exponent & 1 != 0 {
                result = result.mul(base);
            }
            base = base.square();
            exponent >>= 1;
        }
        result
    }

    /// Mixed multiplication `(a+b*v)*r = ar + br*v`, for `r` in QM31.
    #[inline(always)]
    pub fn mul_qm31(self, rhs: QM31) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::EMulK);
        let rhs = canonical_qm31(rhs);
        Self {
            c0: self.c0.mul(rhs),
            c1: self.c1.mul(rhs),
        }
    }

    /// Scalar multiplication without lifting to a full E product.
    #[inline(always)]
    #[cfg(not(feature = "ct-host-prover"))] pub fn mul_m31(self, rhs: M31) -> Self {
        #[cfg(feature = "r0-op-count")]
        let _count = crate::r0_op_count::enter(crate::r0_op_count::Op::EMulF);
        let rhs = M31(rhs.0 % P);
        Self {
            c0: self.c0.mul_m31(rhs),
            c1: self.c1.mul_m31(rhs),
        }
    }

    #[cfg(not(feature = "ct-host-prover"))] pub fn is_zero(self) -> bool {
        self.c0.is_zero() && self.c1.is_zero()
    }

    /// Decode eight base-P digits without reduction; rejects any digit >= P.
    /// This is `digitsField`, not the natural-number cast of a base-P rank.
    #[inline(always)]
    pub fn from_limbs(limbs: [u32; Self::LIMB_COUNT]) -> Option<Self> {
        if limbs[0] >= P || limbs[1] >= P || limbs[2] >= P || limbs[3] >= P
            || limbs[4] >= P || limbs[5] >= P || limbs[6] >= P || limbs[7] >= P {
            return None;
        }
        let [a, b, c, d, e, f, g, h] = limbs;
        Some(Self {
            c0: QM31 {
                c0: CM31 {
                    a: M31(a),
                    b: M31(b),
                },
                c1: CM31 {
                    a: M31(c),
                    b: M31(d),
                },
            },
            c1: QM31 {
                c0: CM31 {
                    a: M31(e),
                    b: M31(f),
                },
                c1: CM31 {
                    a: M31(g),
                    b: M31(h),
                },
            },
        })
    }

    #[inline(always)]
    pub const fn to_limbs(self) -> [u32; Self::LIMB_COUNT] {
        [
            self.c0.c0.a.0,
            self.c0.c0.b.0,
            self.c0.c1.a.0,
            self.c0.c1.b.0,
            self.c1.c0.a.0,
            self.c1.c0.b.0,
            self.c1.c1.a.0,
            self.c1.c1.b.0,
        ]
    }

    /// Exactly 32 bytes: eight little-endian u32 limbs in `digitsField` order.
    /// Rejects both wrong lengths and noncanonical limbs, without slicing an
    /// unvalidated input. This is a field encoding, not the R-B block sampler.
    #[inline(always)]
    pub fn from_le_bytes(bytes: &[u8]) -> Option<Self> {
        if bytes.len() != Self::BYTE_LEN {
            return None;
        }
        let limbs = [
            u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]),
            u32::from_le_bytes([bytes[4], bytes[5], bytes[6], bytes[7]]),
            u32::from_le_bytes([bytes[8], bytes[9], bytes[10], bytes[11]]),
            u32::from_le_bytes([bytes[12], bytes[13], bytes[14], bytes[15]]),
            u32::from_le_bytes([bytes[16], bytes[17], bytes[18], bytes[19]]),
            u32::from_le_bytes([bytes[20], bytes[21], bytes[22], bytes[23]]),
            u32::from_le_bytes([bytes[24], bytes[25], bytes[26], bytes[27]]),
            u32::from_le_bytes([bytes[28], bytes[29], bytes[30], bytes[31]]),
        ];
        Self::from_limbs(limbs)
    }

    #[inline(always)]
    pub fn to_le_bytes(self) -> [u8; Self::BYTE_LEN] {
        let mut bytes = [0; Self::BYTE_LEN];
        for (chunk, limb) in bytes.chunks_exact_mut(4).zip(self.to_limbs()) {
            chunk.copy_from_slice(&limb.to_le_bytes());
        }
        bytes
    }
}

#[inline(always)]
#[cfg(not(feature = "ct-host-prover"))] fn canonical_qm31(value: QM31) -> QM31 {
    let reduce = |x: M31| M31(x.0 % P);
    QM31 {
        c0: CM31 {
            a: reduce(value.c0.a),
            b: reduce(value.c0.b),
        },
        c1: CM31 {
            a: reduce(value.c1.a),
            b: reduce(value.c1.b),
        },
    }
}

/// `u*(a+b*u) = (2+i)*b + a*u`.
#[inline(always)]
fn mul_u(value: QM31) -> QM31 {
    QM31 {
        c0: super::mul_by_r(value.c1),
        c1: value.c0,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn next(state: &mut u64) -> WideExact {
        WideExact::from_limbs(core::array::from_fn(|_| {
            *state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            (*state % u64::from(P)) as u32
        }))
        .unwrap()
    }

    fn basis(index: usize) -> WideExact {
        let mut limbs = [0; 8];
        limbs[index] = 1;
        WideExact::from_limbs(limbs).unwrap()
    }

    fn assert_canonical(x: WideExact) {
        assert!(x.to_limbs().iter().all(|&d| d < P));
    }

    // Independent schoolbook polynomial oracle over integer coefficients.
    // No M31/CM31/QM31 arithmetic: reduce v^2=u, u^2=2+i, i^2=-1,
    // then reduce signed integer coefficients modulo P.
    fn polynomial_product(a: [u32; 8], b: [u32; 8]) -> [u32; 8] {
        let mut coefficients = [0i128; 8];
        for (j, a) in a.into_iter().enumerate() {
            for (k, b) in b.into_iter().enumerate() {
                let i = (j & 1) + (k & 1);
                let v = (j >> 2) + (k >> 2);
                let u = ((j >> 1) & 1) + ((k >> 1) & 1) + v / 2;
                let mut term = |i: usize, scale: i128| {
                    let index = (i % 2) + 2 * (u % 2) + 4 * (v % 2);
                    let sign = if i / 2 % 2 == 0 { 1 } else { -1 };
                    coefficients[index] += sign * scale * i128::from(a) * i128::from(b);
                };
                if u >= 2 {
                    term(i, 2);
                    term(i + 1, 1);
                } else {
                    term(i, 1);
                }
            }
        }
        coefficients.map(|c| c.rem_euclid(i128::from(P)) as u32)
    }

    #[test]
    fn wide_exact_hand_computed_products() {
        let one = WideExact::ONE;
        let i = basis(1);
        let u = basis(2);
        let v = WideExact::V;
        assert_eq!(v, basis(4));
        assert_eq!(WideExact::from_qm31(WideExact::U), u);
        assert_eq!(WideExact::default(), WideExact::ZERO);
        assert_eq!(v.square(), u);
        assert_eq!(u.square().to_limbs(), [2, 1, 0, 0, 0, 0, 0, 0]);
        assert_eq!(i.square(), one.neg());
        // (1+v)(1-v) = 1-u; (u+v)(u-v) = 2+i-u.
        assert_eq!(
            one.add(v).mul(one.sub(v)).to_limbs(),
            [1, 0, P - 1, 0, 0, 0, 0, 0]
        );
        assert_eq!(
            u.add(v).mul(u.sub(v)).to_limbs(),
            [2, 1, P - 1, 0, 0, 0, 0, 0]
        );
        // (iv)(uv) = i*u*v^2 = i*(2+i) = -1+2i.
        assert_eq!(
            basis(5).mul(basis(6)).to_limbs(),
            [P - 1, 2, 0, 0, 0, 0, 0, 0]
        );
        // (1+i+u+v)^2 = (2+3i)+(3+2i)u+(2+2i+2u)v.
        assert_eq!(
            one.add(i).add(u).add(v).square().to_limbs(),
            [2, 3, 3, 2, 2, 2, 2, 0]
        );
        // Dense hand calculation, with a,b the low/high coordinates of x,
        // and c,d those of y:
        // ac=(-49+99i)+(-8+70i)u; bd=(-9+91i)+(8+70i)u;
        // ad=(-9+35i)+30iu; bc=(-81+251i)+174iu.
        // ac+u*bd=(-103+247i)+(-17+161i)u; ad+bc=(-90+286i)+204iu.
        let x = WideExact::from_limbs([1, 2, 3, 4, 5, 6, 7, 8]).unwrap();
        let y = WideExact::from_limbs([8, 7, 6, 5, 4, 3, 2, 1]).unwrap();
        assert_eq!(
            x.mul(y).to_limbs(),
            [P - 103, 247, P - 17, 161, P - 90, 286, 0, 204]
        );
        // v^-1 = ((2-i)/5)*u*v, with 1/5 = 858993459 mod P.
        assert_eq!(
            v.try_inv().unwrap().to_limbs(),
            [0, 0, 0, 0, 0, 0, 1717986918, 1288490188]
        );
    }

    #[test]
    fn wide_exact_products_match_independent_polynomial_oracle() {
        for j in 0..8 {
            for k in 0..8 {
                let a = basis(j);
                let b = basis(k);
                assert_eq!(
                    a.mul(b).to_limbs(),
                    polynomial_product(a.to_limbs(), b.to_limbs())
                );
            }
        }
        let mut state = 0x5749_4445_5241_0001;
        for _ in 0..1024 {
            let a = next(&mut state);
            let b = next(&mut state);
            assert_eq!(
                a.mul(b).to_limbs(),
                polynomial_product(a.to_limbs(), b.to_limbs())
            );
        }
        let high = WideExact::from_limbs([P - 1; 8]).unwrap();
        assert_eq!(
            high.square().to_limbs(),
            polynomial_product([P - 1; 8], [P - 1; 8])
        );
    }

    #[test]
    fn wide_exact_random_ring_laws_and_canonical_outputs() {
        let mut state = 0x5749_4445_5241_0002;
        for _ in 0..4096 {
            let a = next(&mut state);
            let b = next(&mut state);
            let c = next(&mut state);
            assert_eq!(a.add(b), b.add(a));
            assert_eq!(a.add(b).add(c), a.add(b.add(c)));
            assert_eq!(a.mul(b), b.mul(a));
            assert_eq!(a.mul(b).mul(c), a.mul(b.mul(c)));
            assert_eq!(a.mul(b.add(c)), a.mul(b).add(a.mul(c)));
            assert_eq!(a.add(WideExact::ZERO), a);
            assert_eq!(a.mul(WideExact::ONE), a);
            assert_eq!(a.mul(WideExact::ZERO), WideExact::ZERO);
            assert_eq!(a.add(a.neg()), WideExact::ZERO);
            assert_eq!(a.sub(b), a.add(b.neg()));
            assert_eq!(a.add(b).sub(b), a);
            assert_eq!(a.neg().neg(), a);
            assert_eq!(a.square(), a.mul(a));
            for x in [a.add(b), a.sub(b), a.neg(), a.mul(b), a.square()] {
                assert_canonical(x);
            }
        }
    }

    #[test]
    fn wide_exact_inverse_roundtrips_including_edges() {
        assert_eq!(WideExact::ZERO.try_inv(), None);
        let mut state = 0x5749_4445_5241_0003;
        for a in (0..8)
            .map(basis)
            .chain([
                WideExact::ONE.neg(),
                WideExact::from_limbs([P - 1; 8]).unwrap(),
            ])
            .chain((0..1024).map(|_| next(&mut state)))
        {
            let inverse = a.try_inv().unwrap();
            assert_eq!(a.mul(inverse), WideExact::ONE);
            assert_eq!(inverse.mul(a), WideExact::ONE);
            assert_eq!(inverse.try_inv(), Some(a));
            assert_canonical(inverse);
        }
    }

    #[test]
    fn wide_exact_pow_and_qm31_embedding() {
        assert_eq!(WideExact::ZERO.pow(0), WideExact::ONE);
        assert_eq!(WideExact::ZERO.pow(1), WideExact::ZERO);
        let mut state = 0x5749_4445_5241_0004;
        for _ in 0..128 {
            let a = next(&mut state);
            let b = next(&mut state);
            let x = WideExact::from_qm31(a.c0());
            let y = WideExact::from_qm31(b.c0());
            assert_eq!(x.c0(), a.c0());
            assert_eq!(x.c1(), QM31::ZERO);
            assert_eq!(x.mul(y), WideExact::from_qm31(a.c0().mul(b.c0())));
            assert_eq!(x.add(y), WideExact::from_qm31(a.c0().add(b.c0())));
            assert_eq!(a.mul_qm31(b.c0()), a.mul(y));
            assert_eq!(a.mul_qm31(QM31::ZERO), WideExact::ZERO);
            assert_eq!(a.mul_qm31(QM31::ONE), a);
            let mut repeated = WideExact::ONE;
            for exponent in 0..32 {
                assert_eq!(a.pow(exponent), repeated);
                repeated = repeated.mul(a);
            }
            assert_eq!(a.pow(u64::MAX), a.pow(u64::MAX - 1).mul(a));
            // |E|=P^8: eight P-power Frobenius applications fix each element.
            let mut frobenius = a;
            for _ in 0..8 {
                frobenius = frobenius.pow(u64::from(P));
            }
            assert_eq!(frobenius, a);
        }
    }

    #[test]
    fn wide_exact_u_is_not_a_sampled_qm31_square() {
        // Reference fact: WideTower.lean:qm31_wideU_not_isSquare.
        // Sampling is a regression check, not a replacement for that proof.
        let mut state = 0x5749_4445_5241_0005;
        for x in [QM31::ZERO, QM31::ONE, WideExact::U]
            .into_iter()
            .chain((0..4096).map(|_| next(&mut state).c0()))
        {
            assert_ne!(x.square(), WideExact::U);
        }
        // Euler criterion, independently pinning u rather than another non-residue.
        let mut exponent = (u128::from(P).pow(4) - 1) / 2;
        let mut base = WideExact::U;
        let mut result = QM31::ONE;
        while exponent != 0 {
            if exponent & 1 != 0 {
                result = result.mul(base);
            }
            base = base.square();
            exponent >>= 1;
        }
        assert_eq!(result, QM31::ONE.neg());
        let mut v = WideExact::V;
        for _ in 0..4 {
            v = v.pow(u64::from(P));
        }
        assert_eq!(v, WideExact::V.neg()); // v is outside the QM31 subfield.
    }

    #[test]
    fn wide_exact_canonical_digits_and_bytes_roundtrip() {
        assert_eq!(WideExact::LIMB_COUNT, 8);
        assert_eq!(core::mem::size_of::<WideExact>(), 32);
        let mut state = 0x5749_4445_5241_0006;
        for x in [
            WideExact::ZERO,
            WideExact::ONE,
            WideExact::from_limbs([P - 1; 8]).unwrap(),
        ]
        .into_iter()
        .chain((0..1024).map(|_| next(&mut state)))
        {
            assert_eq!(WideExact::from_limbs(x.to_limbs()), Some(x));
            assert_eq!(WideExact::from_le_bytes(&x.to_le_bytes()), Some(x));
        }
        // Explicit byte/lane ordering, independently of the round-trip.
        let limbs = [1, 2, 3, 4, 5, 6, 7, 8];
        let x = WideExact::from_limbs(limbs).unwrap();
        assert_eq!(
            x.c0(),
            QM31 {
                c0: CM31::new(M31(1), M31(2)),
                c1: CM31::new(M31(3), M31(4))
            }
        );
        assert_eq!(
            x.c1(),
            QM31 {
                c0: CM31::new(M31(5), M31(6)),
                c1: CM31::new(M31(7), M31(8))
            }
        );
        assert_eq!(
            x.to_le_bytes(),
            [
                1, 0, 0, 0, 2, 0, 0, 0, 3, 0, 0, 0, 4, 0, 0, 0, 5, 0, 0, 0, 6, 0, 0, 0, 7, 0, 0, 0,
                8, 0, 0, 0
            ]
        );
        let x = WideExact::from_limbs([0x12345678; 8]).unwrap();
        assert!(x
            .to_le_bytes()
            .chunks_exact(4)
            .all(|b| b == [0x78, 0x56, 0x34, 0x12]));
    }

    #[test]
    fn wide_exact_rejects_malformed_encodings_without_panics() {
        let bytes = [0u8; 65];
        for len in 0..=65 {
            assert_eq!(
                WideExact::from_le_bytes(&bytes[..len]),
                if len == 32 {
                    Some(WideExact::ZERO)
                } else {
                    None
                }
            );
        }
        for index in 0..8 {
            for invalid in [P, P + 1, u32::MAX] {
                let mut limbs = [0; 8];
                limbs[index] = invalid;
                assert_eq!(WideExact::from_limbs(limbs), None);
                let mut bytes = [0; 32];
                bytes[4 * index..4 * index + 4].copy_from_slice(&invalid.to_le_bytes());
                assert_eq!(WideExact::from_le_bytes(&bytes), None);
            }
        }
    }

    #[test]
    fn wide_exact_algebraic_constructors_canonicalize_raw_qm31() {
        let raw = QM31 {
            c0: CM31::new(M31(P), M31(P + 1)),
            c1: CM31::new(M31(u32::MAX), M31(P - 1)),
        };
        let x = WideExact::new(raw, raw);
        assert_eq!(x.to_limbs(), [0, 1, 1, P - 1, 0, 1, 1, P - 1]);
        let embedded = WideExact::from_qm31(raw);
        assert_eq!(embedded.to_limbs(), [0, 1, 1, P - 1, 0, 0, 0, 0]);
        assert_eq!(x.mul_qm31(raw), x.mul(embedded));
        assert_eq!(x.mul(x.try_inv().unwrap()), WideExact::ONE);
        assert_canonical(x.add(x));
        assert_canonical(x.sub(x.neg()));
    }
}

#[cfg(feature = "ct-host-prover")]
#[inline(always)]
fn canonical_qm31(value: QM31) -> QM31 {
    let reduce = |x: M31| M31(super::ct::reduce64(x.0 as u64));
    QM31 { c0: CM31 { a: reduce(value.c0.a), b: reduce(value.c0.b) }, c1: CM31 { a: reduce(value.c1.a), b: reduce(value.c1.b) } }
}
#[cfg(feature = "ct-host-prover")]
impl WideExact {
    #[inline(always)]
    pub fn mul_m31(self, rhs: M31) -> Self {
        let rhs = M31(super::ct::reduce64(rhs.0 as u64));
        Self { c0: self.c0.mul_m31(rhs), c1: self.c1.mul_m31(rhs) }
    }
    #[inline(always)]
    pub fn is_zero(self) -> bool { self.c0.is_zero() & self.c1.is_zero() }
}

//! UNPROVED COST PROBE. Own native prover, including D14 content.
use alloc::{vec,vec::Vec};
use aspis_core::{digest::LegacyHashFn,HashFn,field::{WideExact as E,M31,QM31 as K,CM31},r0::{self,CodeField,domain::{Point,FibreIndex},merkle,wire::FibreOpening,Message},state_only_hiding::StateOnlyHidingContext};
use aspis_statement::pool_v1::{pair_forest_semantic_terminal::r0::Public,pair_forest_trace::PoolV1PairForestMergedC1CompilationV1};
use crate::host_forest::pool_v1_pair_forest_copy_active_row_masks_v1;
use aspis_prover::{state_only_entropy::{StateOnlyAttemptSecrets,ReservedStateOnlyAttemptSecrets,DurableStateOnlyMaskNonceStore},state_only_hiding::{apply_pool_v1_pair_forest_mask_material_v1,InMemoryStateOnlyMaskNonceStore,StateOnlyMaskBuildError,StateOnlyMaskNonceStore}};
use crate::{transport::Variant,verifier::{Error},host_weights::{Weights,QUARTER,PERM},host_transcript::Transcript,host_commitment::{Commitment,CommitmentTime,EncodingDomain,PrivateSalts},host_semantic::{BuiltSemantics,Commitments},r1_wire::Error as SError};
/// Host commitment backend. Adopted format (PREREG-PROOF-SIZE-2): salted
/// leaves under binary trees; there is no unsalted or eight-way commitment.
pub struct Backend {pub hash:HashFn,pub variant:Variant,pub domain:EncodingDomain,pub messages:Vec<Message<E>>,pub c1:Option<Commitment>,pub c2:Option<Commitment>,c1_salts:Option<crate::host_commitment::PrivateSalts>,c2_salts:Option<crate::host_commitment::PrivateSalts>}
impl Commitments for Backend {
    fn c1(&mut self,columns:&[Vec<M31>;26],d:&[K;1024])->Result<[u8;32],SError>{
        let mut lane=0;
        while lane<26 {
            let mut row=0;
            while row<1024 {self.messages[lane][row]=E::from_m31(columns[lane][row]);row+=1;}
            lane+=1;
        }
        let mut row=0;
        while row<1024 {self.messages[28][row]=E::from_qm31(d[row]);row+=1;}

        let salts=self.c1_salts.take().ok_or(SError::Public)?;
        let c=Commitment::new_salted(self.hash,&self.domain,CommitmentTime::C1,&self.messages,self.variant,salts).map_err(|_|SError::Public)?;
        let root=c.root();self.c1=Some(c);Ok(root)
    }
    fn c2(&mut self,h1:&[K],g:&[K;1024])->Result<[u8;32],SError>{
        let mut row=0;
        while row<1024 {self.messages[26][row]=E::from_qm31(h1[row]);row+=1;}
        row=0;
        while row<1024 {self.messages[27][row]=E::from_qm31(g[row]);row+=1;}

        let salts=self.c2_salts.take().ok_or(SError::Public)?;
        let c=Commitment::new_salted(self.hash,&self.domain,CommitmentTime::C2,&self.messages,self.variant,salts).map_err(|_|SError::Public)?;
        let root=c.root();self.c2=Some(c);Ok(root)
    }
}
pub fn round(q:&[E],w:&[E])->[E;7] {
    assert_eq!(q.len(),w.len());
    let mut c=[E::ZERO;7];
    let mut d=0;
    while d<q.len()/4 {
        let mut s=0;
        while s<4 {
            let mut t=0;
            while t<4 {
                let at=s+PERM[t];
                c[at]=c[at].add(q[4*d+s].mul(w[4*d+t]));
                t+=1;
            }
            s+=1;
        }
        d+=1;
    }
    let mut i=0;
    while i<7 {c[i]=c[i].mul_m31(QUARTER);i+=1;}
    c
}
pub fn fold(q:&[E],alpha:E,dual:bool)->Vec<E> {
    let mut out=Vec::with_capacity(q.len()/4);
    let mut i=0;
    while i<q.len()/4 {
        let h=[q[4*i],q[4*i+1],q[4*i+2],q[4*i+3]];
        let value=fold_cell(h,alpha,dual);
        out.push(value);i+=1;
    }
    out
}

#[inline(always)]
fn fold_cell(h:[E;4],alpha:E,dual:bool)->E {
    if dual {
            h[0].add(alpha.mul(h[3].add(alpha.mul(h[2].add(alpha.mul(h[1])))))).mul_m31(QUARTER)
        } else {
            h[0].add(alpha.mul(h[1].add(alpha.mul(h[2].add(alpha.mul(h[3]))))))
        }
}

/// Ordered byte assembly used by the real pipeline; each field encoding is a leaf.
fn encoded_slice(values:&[E])->Vec<u8> {
    let mut out=Vec::with_capacity(32*values.len());
    let mut i=0;
    while i<values.len() {out.extend_from_slice(&values[i].to_le_bytes());i+=1;}
    out
}

pub fn encoded(values:impl IntoIterator<Item=E>)->Vec<u8> {values.into_iter().flat_map(E::to_le_bytes).collect()}

/// Deterministic fixture-only rejection sampling of K limbs. No distribution
/// property is inferred from these fixed test samples.
fn tail_samples(hash:HashFn,seed:&[u8;32])->[K;56] {
    let mut counter=0u64;
    let mut limb=||loop {
        let b=hash(&[b"UNPROVED:R1:P2:fixture-tail",seed,&counter.to_le_bytes()]);counter+=1;
        let x=u32::from_le_bytes(b[..4].try_into().unwrap())&0x7fffffff;
        if x<aspis_core::field::P {break M31(x);}
    };
    core::array::from_fn(|_|K{c0:CM31::new(limb(),limb()),c1:CM31::new(limb(),limb())})
}
/// Convenience API, deliberately fixture-only: it always emits a fully masked
/// P3 proof in the adopted compact binary-multiproof format.
pub fn prove(public:Public<'_>,compiled:&PoolV1PairForestMergedC1CompilationV1,variant:Variant,hash:HashFn,seed:&[u8;32])->Result<Vec<u8>,Error> {
    prove_masked_fixture(public,compiled,variant,hash,seed).map(|(proof,_)|proof)
